import { useState, useRef, useCallback, useEffect } from 'react';

const API_BASE = 'http://localhost:5001';

const FIELD_LABELS = {
  shoot_height_cm:        'Shoot Height',
  trunk_circumference_cm: 'Trunk Circumference',
  shoot_age_months:       'Shoot Age',
  num_leaves:             'No. of Leaves',
  leaf_color:             'Leaf Colour',
  bark_texture:           'Bark Texture',
  bark_color:             'Bark Colour',
  straightness:           'Straightness',
};

const FIELD_UNITS = {
  shoot_height_cm: 'cm',
  trunk_circumference_cm: 'cm',
  shoot_age_months: 'mo',
};

// Professional SVG icons
const Icons = {
  ruler: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
      <path d="M2 18L18 2l4 4L6 22z"/><path d="M9 9l6 6"/><path d="M6 12l3 3"/><path d="M12 6l3 3"/>
    </svg>
  ),
  trunk: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
      <circle cx="12" cy="12" r="4"/><circle cx="12" cy="12" r="9"/>
    </svg>
  ),
  calendar: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
      <rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/>
    </svg>
  ),
  leaf: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
      <path d="M11 20A7 7 0 0 1 9.8 6.1C15.5 5 17 4.48 19 2c1 2 2 4.18 2 8 0 5.5-4.78 10-10 10z"/><path d="M2 21c0-3 1.85-5.36 5.08-6C9.5 14.52 12 13 13 12"/>
    </svg>
  ),
  color: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
      <circle cx="12" cy="12" r="10"/><path d="M12 2a10 10 0 0 1 0 20"/><path d="M2 12h20"/>
    </svg>
  ),
  texture: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
      <path d="M4 6h16M4 10h16M4 14h16M4 18h16"/>
    </svg>
  ),
  align: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
      <path d="M12 2v20M2 12h20"/>
    </svg>
  ),
  mic: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
      <path d="M12 2a3 3 0 0 1 3 3v7a3 3 0 0 1-6 0V5a3 3 0 0 1 3-3z"/><path d="M19 10v2a7 7 0 0 1-14 0v-2"/><path d="M12 19v3M9 22h6"/>
    </svg>
  ),
  stop: (
    <svg viewBox="0 0 24 24" fill="currentColor">
      <rect x="6" y="6" width="12" height="12" rx="2"/>
    </svg>
  ),
  search: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/>
    </svg>
  ),
  checkCircle: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><path d="M22 4 12 14.01l-3-3"/>
    </svg>
  ),
  clock: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/>
    </svg>
  ),
  xCircle: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <circle cx="12" cy="12" r="10"/><path d="m15 9-6 6M9 9l6 6"/>
    </svg>
  ),
  info: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <circle cx="12" cy="12" r="10"/><path d="M12 16v-4M12 8h.01"/>
    </svg>
  ),
  chart: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
      <path d="M3 3v18h18"/><path d="M18 9l-5 5-4-4-3 3"/>
    </svg>
  ),
  detect: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
      <path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7z"/><circle cx="12" cy="12" r="3"/>
    </svg>
  ),
  plantHealth: (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
      <path d="M12 22c-4.97 0-9-2.69-9-6 0-1.5.83-2.9 2.2-3.9A9.98 9.98 0 0 1 12 2c3.31 0 6.2 1.6 8 4"/><path d="M20 11.5a8.84 8.84 0 0 1-1.5 5c-1.3 1.9-3.3 3.5-6.5 3.5"/>
      <path d="M9 12c0 1.66 1.34 3 3 3s3-1.34 3-3"/>
    </svg>
  ),
};

const FIELD_ICONS_MAP = {
  shoot_height_cm: Icons.ruler,
  trunk_circumference_cm: Icons.trunk,
  shoot_age_months: Icons.calendar,
  num_leaves: Icons.leaf,
  leaf_color: Icons.color,
  bark_texture: Icons.texture,
  bark_color: Icons.color,
  straightness: Icons.align,
};

const VERDICT_CONFIG = {
  'Ready':        { icon: Icons.checkCircle, color: '#1a7a45', bg: 'linear-gradient(135deg,#e8f8ef 0%,#d0f0e0 100%)', border: '#a8dfc0', textColor: '#0f5c32', label: 'Ready for Harvest', sub: 'Coppice at 6 cm from ground at 45° angle for best yield.' },
  'Nearly Ready': { icon: Icons.clock,       color: '#9a6800', bg: 'linear-gradient(135deg,#fdf8e8 0%,#faedc0 100%)', border: '#e8cc70', textColor: '#7a5200', label: 'Nearly Ready',       sub: 'Check again in 2–3 weeks for optimal harvest timing.' },
  'Not Ready':    { icon: Icons.xCircle,     color: '#1a5a9a', bg: 'linear-gradient(135deg,#e8f0fc 0%,#ccddf8 100%)', border: '#90b8ef', textColor: '#1a3f78', label: 'Not Ready Yet',      sub: 'The shoot needs more time to develop and mature.' },
};

/* ── Global CSS ─────────────────────────────────────────────────────────────── */
const CSS = `
  @import url('https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700&family=Lora:wght@600;700&display=swap');

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  html { scroll-behavior: smooth; }
  body { font-family: 'Poppins', sans-serif; background: #f0f7f2; -webkit-font-smoothing: antialiased; }

  @keyframes fadeUp   { from { opacity:0; transform:translateY(18px); } to { opacity:1; transform:translateY(0); } }
  @keyframes fadeIn   { from { opacity:0; } to { opacity:1; } }
  @keyframes spin     { to { transform:rotate(360deg); } }
  @keyframes barGrow  { from { width:0%; } }
  @keyframes pulse    { 0%,100%{opacity:1;} 50%{opacity:0.5;} }
  @keyframes ripple   {
    0%   { transform:scale(1); box-shadow:0 0 0 0 rgba(26,122,69,0.35); }
    70%  { transform:scale(1); box-shadow:0 0 0 12px rgba(26,122,69,0); }
    100% { transform:scale(1); box-shadow:0 0 0 0 rgba(26,122,69,0); }
  }
  @keyframes recPulse {
    0%,100%{ box-shadow:0 0 0 0 rgba(220,53,69,0.4); }
    50%    { box-shadow:0 0 0 10px rgba(220,53,69,0); }
  }
  @keyframes shimmer {
    0%   { background-position:-400px 0; }
    100% { background-position:400px 0; }
  }

  /* ── Layout ── */
  .ch { min-height:100vh; background:#f0f7f2; }

  /* ── Hero ── */
  .ch-hero {
    position:relative; overflow:hidden;
    background:linear-gradient(145deg, #ffffff 0%, #e8f5ee 40%, #d4edde 100%);
    border-bottom:1px solid #c8e6d4;
    padding:0;
  }
  .ch-hero-img {
    width:100%; height:220px; object-fit:cover; display:block;
    filter:brightness(0.88) saturate(1.1);
  }
  .ch-hero-overlay {
    position:absolute; inset:0;
    background:linear-gradient(to bottom, rgba(255,255,255,0.05) 0%, rgba(240,247,242,0.75) 60%, rgba(240,247,242,1) 100%);
  }
  .ch-hero-content {
    position:absolute; bottom:0; left:0; right:0;
    padding:16px 20px 20px;
    animation: fadeUp 0.6s ease both;
  }
  .ch-hero-chip {
    display:inline-flex; align-items:center; gap:5px;
    background:rgba(26,122,69,0.1); border:1px solid rgba(26,122,69,0.22);
    border-radius:20px; padding:3px 10px;
    font-size:0.65rem; font-weight:600; letter-spacing:0.08em; text-transform:uppercase;
    color:#1a7a45; margin-bottom:7px;
  }
  .ch-hero-chip svg { width:10px; height:10px; }
  .ch-hero-title {
    font-family:'Lora',Georgia,serif;
    font-size:clamp(1.3rem,4vw,1.7rem); font-weight:700; color:#0f3d22; line-height:1.2;
  }
  .ch-hero-title span { color:#1a7a45; }
  .ch-hero-sub { font-size:0.72rem; color:#5a7a65; margin-top:4px; font-weight:400; }

  /* ── Main body ── */
  .ch-body {
    max-width:680px; margin:0 auto;
    padding:18px 14px 50px;
  }

  /* ── Card ── */
  .ch-card {
    background:#ffffff; border:1px solid #dceee4;
    border-radius:18px; margin-bottom:14px;
    box-shadow:0 2px 12px rgba(26,122,69,0.06);
    overflow:hidden; animation:fadeUp 0.4s ease both;
    transition: box-shadow 0.2s;
  }
  .ch-card:hover { box-shadow:0 4px 20px rgba(26,122,69,0.10); }
  .ch-card-hdr {
    display:flex; align-items:center; gap:10px;
    padding:14px 16px 0;
  }
  .ch-card-ico {
    width:32px; height:32px; border-radius:9px; flex-shrink:0;
    background:#e8f5ee; border:1px solid #c8e6d4;
    display:flex; align-items:center; justify-content:center;
    color:#1a7a45;
  }
  .ch-card-ico svg { width:16px; height:16px; }
  .ch-card-ttl { font-size:0.73rem; font-weight:700; color:#1a7a45; text-transform:uppercase; letter-spacing:0.08em; }
  .ch-card-body { padding:12px 16px 16px; }

  /* ── Input area ── */
  .ch-input-wrap { position:relative; }
  .ch-ta {
    width:100%; min-height:104px;
    background:#f7fdf9; border:1.5px solid #c8e6d4;
    border-radius:13px; padding:12px 52px 12px 14px;
    font-family:'Poppins',sans-serif; font-size:0.9rem; line-height:1.65;
    color:#1a3020; resize:none; outline:none;
    transition:border-color 0.2s, background 0.2s, box-shadow 0.2s;
  }
  .ch-ta::placeholder { color:#9abaa8; font-size:0.83rem; }
  .ch-ta:focus {
    border-color:#1a7a45; background:#fff;
    box-shadow:0 0 0 3px rgba(26,122,69,0.08);
  }

  /* ── Mic button ── */
  .ch-mic {
    position:absolute; right:10px; bottom:10px;
    width:36px; height:36px; border-radius:50%; border:none; cursor:pointer;
    display:flex; align-items:center; justify-content:center;
    transition:all 0.2s; flex-shrink:0;
  }
  .ch-mic svg { width:16px; height:16px; }
  .ch-mic.idle {
    background:#e8f5ee; border:1.5px solid #c8e6d4; color:#1a7a45;
  }
  .ch-mic.idle:hover { background:#d4edde; }
  .ch-mic.rec {
    background:#dc3545; color:#fff; border:1.5px solid #dc3545;
    animation:recPulse 1.4s infinite;
  }

  .ch-hint {
    display:flex; align-items:center; gap:6px;
    font-size:0.68rem; color:#7a9a85; margin-top:7px; padding:0 2px;
  }
  .ch-hint svg { width:12px; height:12px; color:#1a7a45; flex-shrink:0; }

  /* ── Analyze button ── */
  .ch-btn {
    width:100%; padding:14px; margin-top:12px;
    border:none; border-radius:13px;
    font-family:'Poppins',sans-serif; font-size:0.94rem; font-weight:600;
    cursor:pointer; letter-spacing:0.01em;
    display:flex; align-items:center; justify-content:center; gap:8px;
    position:relative; overflow:hidden; transition:all 0.25s;
  }
  .ch-btn svg { width:18px; height:18px; }
  .ch-btn.on {
    background:linear-gradient(135deg,#1a7a45 0%,#28a05e 100%);
    color:#fff;
    box-shadow:0 6px 20px rgba(26,122,69,0.28);
    animation:ripple 2s infinite;
  }
  .ch-btn.on:hover  { transform:translateY(-1px); box-shadow:0 8px 24px rgba(26,122,69,0.36); }
  .ch-btn.on:active { transform:translateY(0); box-shadow:0 3px 10px rgba(26,122,69,0.2); }
  .ch-btn.off {
    background:#e8f5ee; color:#9abaa8; cursor:not-allowed;
    border:1px solid #c8e6d4;
  }
  .ch-btn-shimmer {
    position:absolute; inset:0;
    background:linear-gradient(90deg,transparent 0%,rgba(255,255,255,0.2) 50%,transparent 100%);
    background-size:400px 100%; animation:shimmer 1.5s infinite;
  }

  /* ── Spinner ── */
  .ch-spin {
    width:18px; height:18px; border-radius:50%;
    border:2px solid rgba(255,255,255,0.3);
    border-top-color:#fff;
    animation:spin 0.7s linear infinite; flex-shrink:0;
  }
  .ch-spin-green {
    width:18px; height:18px; border-radius:50%;
    border:2px solid rgba(26,122,69,0.15);
    border-top-color:#1a7a45;
    animation:spin 0.7s linear infinite; flex-shrink:0;
  }

  /* ── Loading status ── */
  .ch-loading {
    display:flex; align-items:center; gap:10px;
    background:#fff; border:1px solid #dceee4; border-radius:13px;
    padding:14px 16px; margin-bottom:14px;
    font-size:0.83rem; color:#4a7a58;
    animation:fadeIn 0.3s ease;
  }

  /* ── Error ── */
  .ch-err {
    background:#fff5f5; border:1px solid #fcc; border-radius:13px;
    padding:13px 15px; font-size:0.82rem; color:#c0392b;
    margin-bottom:14px; line-height:1.55; animation:fadeUp 0.3s ease;
  }
  .ch-err-title { font-weight:600; margin-bottom:3px; display:flex; align-items:center; gap:6px; }
  .ch-err-title svg { width:16px; height:16px; }
  .ch-err-hint { font-size:0.72rem; color:#999; margin-top:5px; }

  /* ── Parsed fields grid ── */
  .ch-grid {
    display:grid;
    grid-template-columns:repeat(auto-fill, minmax(140px,1fr));
    gap:9px;
  }
  .ch-pill {
    background:#f7fdf9; border:1px solid #dceee4; border-radius:11px;
    padding:10px 12px; animation:fadeUp 0.3s ease both;
    transition:border-color 0.2s;
  }
  .ch-pill:hover { border-color:#1a7a45; }
  .ch-pill-lbl {
    display:flex; align-items:center; gap:5px;
    font-size:0.6rem; color:#7a9a85; text-transform:uppercase;
    letter-spacing:0.06em; margin-bottom:3px; font-weight:500;
  }
  .ch-pill-lbl svg { width:11px; height:11px; color:#1a7a45; }
  .ch-pill-val { font-size:0.88rem; font-weight:600; color:#0f3d22; }

  /* ── Result banner ── */
  .ch-banner {
    border-radius:18px; padding:18px 20px;
    display:flex; align-items:flex-start; gap:14px;
    margin-bottom:13px; border:1.5px solid transparent;
    animation:fadeUp 0.4s ease;
    position:relative; overflow:hidden;
  }
  .ch-banner-ico-wrap {
    width:44px; height:44px; border-radius:12px; flex-shrink:0;
    display:flex; align-items:center; justify-content:center;
    background:rgba(255,255,255,0.7); border:1px solid rgba(255,255,255,0.9);
  }
  .ch-banner-ico-wrap svg { width:22px; height:22px; }
  .ch-banner-txt { flex:1; }
  .ch-banner-lbl {
    font-family:'Lora',serif; font-size:1.3rem; font-weight:700; line-height:1.2;
    margin-bottom:4px;
  }
  .ch-banner-sub { font-size:0.76rem; line-height:1.5; opacity:0.75; }

  /* ── Confidence bars ── */
  .ch-conf-row { display:flex; align-items:center; gap:10px; margin-bottom:10px; }
  .ch-conf-row:last-child { margin-bottom:0; }
  .ch-conf-lbl { width:106px; font-size:0.75rem; color:#4a6a55; flex-shrink:0; font-weight:500; }
  .ch-conf-track { flex:1; height:7px; background:#e8f5ee; border-radius:6px; overflow:hidden; }
  .ch-conf-fill { height:100%; border-radius:6px; animation:barGrow 0.8s cubic-bezier(0.34,1.56,0.64,1) both; }
  .ch-conf-pct { width:36px; font-size:0.75rem; font-weight:700; text-align:right; }

  /* ── Reasons ── */
  .ch-reasons { display:flex; flex-direction:column; gap:8px; }
  .ch-reason {
    display:flex; gap:10px; align-items:flex-start;
    background:#f7fdf9; border:1px solid #dceee4; border-radius:11px;
    padding:11px 13px; animation:fadeUp 0.35s ease both;
    transition:border-color 0.2s;
  }
  .ch-reason:hover { border-color:#1a7a45; }
  .ch-reason-dot {
    width:7px; height:7px; border-radius:50%; background:#1a7a45;
    flex-shrink:0; margin-top:6px;
    box-shadow:0 0 0 2px rgba(26,122,69,0.15);
  }
  .ch-reason-txt { font-size:0.82rem; line-height:1.58; color:#2a5038; }

  /* ── Responsive ── */
  @media (min-width:640px) {
    .ch-hero-img { height:280px; }
    .ch-hero-content { padding:20px 28px 24px; }
    .ch-body { padding:22px 24px 60px; }
    .ch-card-hdr { padding:16px 20px 0; }
    .ch-card-body { padding:14px 20px 20px; }
    .ch-ta { font-size:0.95rem; min-height:110px; }
  }
  @media (min-width:900px) {
    .ch-hero-img { height:320px; }
    .ch-body { padding:28px 28px 70px; }
  }

  ::-webkit-scrollbar { width:4px; }
  ::-webkit-scrollbar-thumb { background:#c8e6d4; border-radius:4px; }
`;

function useCSS() {
  useEffect(() => {
    const id = 'ch-css';
    if (!document.getElementById(id)) {
      const el = document.createElement('style');
      el.id = id; el.textContent = CSS;
      document.head.appendChild(el);
    }
  }, []);
}

