/* ── Sub-components ──────────────────────────────────────────────────────── */
function ParsedFields({ fields }) {
  const entries = Object.entries(fields).filter(([, v]) => v !== null && v !== undefined);
  if (!entries.length) return null;
  return (
    <div className="ch-card" style={{ animationDelay: '0.1s' }}>
      <div className="ch-card-hdr">
        <div className="ch-card-ico">{Icons.detect}</div>
        <div className="ch-card-ttl">Detected Values</div>
      </div>
      <div className="ch-card-body">
        <div className="ch-grid">
          {entries.map(([k, val], i) => (
            <div className="ch-pill" key={k} style={{ animationDelay: `${i * 0.04}s` }}>
              <div className="ch-pill-lbl">
                {FIELD_ICONS_MAP[k] || Icons.leaf}
                {FIELD_LABELS[k] || k}
              </div>
              <div className="ch-pill-val">
                {String(val)}{FIELD_UNITS[k] ? ` ${FIELD_UNITS[k]}` : ''}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

function ResultCard({ result }) {
  const vc = VERDICT_CONFIG[result.prediction] || VERDICT_CONFIG['Not Ready'];
  const confBars = [
    { label: 'Ready',        key: 'Ready',        color: '#1a7a45' },
    { label: 'Nearly Ready', key: 'Nearly Ready', color: '#c49a20' },
    { label: 'Not Ready',    key: 'Not Ready',    color: '#2d5faf' },
  ];
  return (
    <>
      {/* Banner */}
      <div className="ch-banner" style={{ background: vc.bg, borderColor: vc.border }}>
        <div className="ch-banner-ico-wrap" style={{ color: vc.color }}>
          {vc.icon}
        </div>
        <div className="ch-banner-txt">
          <div className="ch-banner-lbl" style={{ color: vc.textColor }}>{vc.label}</div>
          <div className="ch-banner-sub" style={{ color: vc.textColor }}>{vc.sub}</div>
        </div>
      </div>

      {/* Confidence */}
      <div className="ch-card" style={{ animationDelay: '0.1s' }}>
        <div className="ch-card-hdr">
          <div className="ch-card-ico">{Icons.chart}</div>
          <div className="ch-card-ttl">Confidence Score</div>
        </div>
        <div className="ch-card-body">
          {confBars.map(({ label, key, color }) => (
            <div className="ch-conf-row" key={key}>
              <div className="ch-conf-lbl">{label}</div>
              <div className="ch-conf-track">
                <div className="ch-conf-fill" style={{ width: `${result.confidence?.[key] ?? 0}%`, background: color }} />
              </div>
              <div className="ch-conf-pct" style={{ color }}>{Math.round(result.confidence?.[key] ?? 0)}%</div>
            </div>
          ))}
        </div>
      </div>

      {/* Reasons */}
      <div className="ch-card" style={{ animationDelay: '0.2s' }}>
        <div className="ch-card-hdr">
          <div className="ch-card-ico">{Icons.info}</div>
          <div className="ch-card-ttl">Analysis Details</div>
        </div>
        <div className="ch-card-body">
          <div className="ch-reasons">
            {result.reasons?.map((r, i) => (
              <div className="ch-reason" key={i} style={{ animationDelay: `${i * 0.07}s` }}>
                <div className="ch-reason-dot" />
                <div className="ch-reason-txt">{r}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </>
  );
}

/* ── Main ────────────────────────────────────────────────────────────────── */
export default function CinnamonHarvest() {
  useCSS();

  const [text, setText]       = useState('');
  const [loading, setLoading] = useState(false);
  const [statusMsg, setMsg]   = useState('');
  const [error, setError]     = useState('');
  const [fields, setFields]   = useState(null);
  const [result, setResult]   = useState(null);
  const [recording, setRec]   = useState(false);
  const recRef    = useRef(null);
  const resultRef = useRef(null);

  const toggleVoice = useCallback(() => {
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SR) { alert('Voice input not supported. Use Chrome or Edge.'); return; }
    if (recording) { recRef.current?.stop(); setRec(false); return; }
    const rec = new SR();
    rec.lang = 'en-US'; rec.interimResults = true; rec.continuous = true;
    recRef.current = rec;
    const base = text;
    rec.onresult = e => {
      let int = '', fin = base;
      for (const r of e.results) {
        if (r.isFinal) fin += (fin ? ' ' : '') + r[0].transcript;
        else int = r[0].transcript;
      }
      setText(fin + (int ? ' ' + int : ''));
    };
    rec.onerror = () => setRec(false);
    rec.onend   = () => setRec(false);
    rec.start(); setRec(true);
  }, [recording, text]);

  const analyze = useCallback(async () => {
    if (!text.trim()) return;
    setLoading(true); setError(''); setResult(null); setFields(null);
    try {
      setMsg('Reading your description…');
      const pr = await fetch(`${API_BASE}/api/parse`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text }),
      });
      if (!pr.ok) throw new Error(`Parse failed (${pr.status}): ${await pr.text()}`);
      const parsedFields = (await pr.json()).fields;
      setFields(parsedFields);

      setMsg('Running harvest readiness model…');
      const rr = await fetch(`${API_BASE}/api/predict`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ fields: parsedFields }),
      });
      if (!rr.ok) throw new Error(`Predict failed (${rr.status}): ${await rr.text()}`);
      setResult(await rr.json()); setMsg('');
      setTimeout(() => resultRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 100);
    } catch (e) {
      setError(e.message); setMsg('');
    } finally {
      setLoading(false);
    }
  }, [text]);

  return (
    <div className="ch">

      {/* ── Hero ── */}
      <div className="ch-hero">
        <HeroImage />
        <div className="ch-hero-overlay" />
        <div className="ch-hero-content">
          <div className="ch-hero-chip">
            {Icons.plantHealth}
            Ceylon Cinnamon · CCGI Certified
          </div>
          <div className="ch-hero-title">
            Harvest <span>Readiness</span> Checker
          </div>
          <div className="ch-hero-sub">AI-powered assessment based on shoot measurements</div>
        </div>
      </div>

      {/* ── Body ── */}
      <div className="ch-body">

        {/* Input card */}
        <div className="ch-card" style={{ animationDelay: '0.1s' }}>
          <div className="ch-card-hdr">
            <div className="ch-card-ico">{Icons.mic}</div>
            <div className="ch-card-ttl">Shoot Description</div>
          </div>
          <div className="ch-card-body">
            <div className="ch-input-wrap">
              <textarea
                className="ch-ta"
                value={text}
                onChange={e => setText(e.target.value)}
                onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); analyze(); } }}
                placeholder={'Type or speak shoot details, e.g.:\n"Height 145 cm, trunk 4 cm, age 20 months, yellowish green leaves, rough and peeling bark, medium brown, 15 leaves, very straight"'}
              />
              <button
                className={`ch-mic ${recording ? 'rec' : 'idle'}`}
                onClick={toggleVoice}
                title={recording ? 'Stop recording' : 'Tap to speak'}
              >
                {recording ? Icons.stop : Icons.mic}
              </button>
            </div>
            <div className="ch-hint">
              {Icons.mic}
              Tap mic to speak your measurements · Press Enter to analyze
            </div>
            <button
              className={`ch-btn ${loading || !text.trim() ? 'off' : 'on'}`}
              disabled={loading || !text.trim()}
              onClick={analyze}
            >
              {loading && <div className="ch-btn-shimmer" />}
              {loading
                ? <><div className="ch-spin" /> Analyzing shoot…</>
                : <>{Icons.search} Check Harvest Readiness</>
              }
            </button>
          </div>
        </div>

        {/* Loading */}
        {loading && statusMsg && (
          <div className="ch-loading">
            <div className="ch-spin-green" />
            {statusMsg}
          </div>
        )}

        {/* Error */}
        {error && (
          <div className="ch-err">
            <div className="ch-err-title">{Icons.info} Something went wrong</div>
            {error}
            <div className="ch-err-hint">Make sure Flask backend is running at localhost:5001</div>
          </div>
        )}

        {/* Parsed fields */}
        {fields && <ParsedFields fields={fields} />}

        {/* Result */}
        <div ref={resultRef}>
          {result && <ResultCard result={result} />}
        </div>

      </div>
    </div>
  );
}
